solution:
use xiom.io;
fn is_even(n: Int) -> Bool
  requires: n >= 1
{
  n % 2 == 0
}

fn main() -> Int {
  assert(is_even(2) == true);
  assert(is_even(3) == false);
  assert(is_even(100) == true);
  io.println("All tests passed!");
  return 0;
}
